import{_ as o,a0 as l,w as p,s as a,I as i,x as t,a1 as s,A as r,ao as m}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse(`{"title":"10  个‘ls’命 令面试的问题（二） | LCTT x X-CMD","titleTemplate":false,"description":"10  个‘ls’命 令面试的问题（二） | LCTT (201504) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"10  个‘ls’命 令面试的问题（二） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"10  个‘ls’命 令面试的问题（二） | LCTT (201504) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201504/20150309 10 Useful 'ls' Command Interview Questions--Part 2","title":"10  个‘ls’命 令面试的问题（二）","tag":"201504","desc":""},"relativePath":"201504/20150309 10 Useful 'ls' Command Interview Questions--Part 2.md","filePath":"[post].md"}`),d={name:"201504/20150309 10 Useful 'ls' Command Interview Questions--Part 2.md"};function c(w,e,h,u,f,g){const n=l("Link");return p(),a("div",null,[e[14]||(e[14]=i("h1",{id:"_10-个-ls-命-令面试的问题-二",tabindex:"-1"},[t("10 个‘ls’命 令面试的问题（二） "),i("a",{class:"header-anchor",href:"#_10-个-ls-命-令面试的问题-二","aria-label":"Permalink to “10  个‘ls’命 令面试的问题（二）”"},"​")],-1)),e[15]||(e[15]=i("p",null,"这是关于文件列表命令的第二篇文章，继续探讨‘ls’命令的其他方面。该系列的第一篇文章受到了社区的高度关注，如果你错过了该系列的第一部分，可以访问以下地址：",-1)),i("ul",null,[i("li",null,[s(n,{href:"http://linux.cn/article-5349-1.html"},{default:r(()=>[...e[0]||(e[0]=[t("15 个‘ls’命令的面试问题（一）",-1)])]),_:1})])]),e[16]||(e[16]=m(`<p>这篇文章通过样例来很好地展现‘ls’命令的深入应用，我们加倍小心地来写这篇文章来保持其简洁可理解性，同时又能提供最全面的服务。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/ls-Command-Interview-Questions.jpg" alt="10 Interview Questions on ls Command"></p><p><em>10 ‘ls’ 命令面试的问题</em></p><h3 id="_16-假如你想要以长列表的形式列出目录中的内容-但是不打印文件创建者名称以及文件所属组。看看输出有何不同之处。" tabindex="-1">16. 假如你想要以长列表的形式列出目录中的内容，但是不打印文件创建者名称以及文件所属组。看看输出有何不同之处。### <a class="header-anchor" href="#_16-假如你想要以长列表的形式列出目录中的内容-但是不打印文件创建者名称以及文件所属组。看看输出有何不同之处。" aria-label="Permalink to “16. 假如你想要以长列表的形式列出目录中的内容，但是不打印文件创建者名称以及文件所属组。看看输出有何不同之处。###”">​</a></h3><p>a. ls 命令在与‘-l’选项一起使用时会将文件以长列表格式输出。</p><pre><code># ls -l
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/List-Files-inLong-List-Format.gif" alt="List Files in- Long List Format"></p><p><em>以长格式列出文件</em></p><p>b. ls 命令在与‘-l’和‘--author’一起使用时，会将文件以长列表格式输出并带有文件创建者的名称信息。</p><pre><code># ls -l --author
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/List-Files-By-Author.gif" alt="List Files By Author"></p><p><em>列出文件的创建者</em></p><p>c. ls 命令在与‘-g’选项 一起将会列出文件名但是不带属主名称。</p><pre><code># ls -g
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/List-Files-Without-Printing-Author.gif" alt="List Files Without Printing Owner Name"></p><p><em>列出文件但不列出属主</em></p><p>d. ls 命令在与&#39;-G&#39;和‘-l’选项一起将会使用长列表格式列出文件名称但是不带文件所属组名称。</p><pre><code># ls -Gl
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/List-Files-Without-Printing-Group.gif" alt="List Files Without Printing Group"></p><p><em>列出文件但是不列出所属组</em></p><h3 id="_17-使用易读格式打印出当前目录中的文件以及文件夹的大小-你会如何做" tabindex="-1">17. 使用易读格式打印出当前目录中的文件以及文件夹的大小，你会如何做？### <a class="header-anchor" href="#_17-使用易读格式打印出当前目录中的文件以及文件夹的大小-你会如何做" aria-label="Permalink to “17. 使用易读格式打印出当前目录中的文件以及文件夹的大小，你会如何做？###”">​</a></h3><p>这里我们需要使用&#39;-h&#39;选项（人类可阅读的、易读的）同‘-l’或‘-s’选项与ls命令一起使用来得到想要的输出。</p><pre><code># ls -hl
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/List-Size-of-Files-with-ls.gif" alt="List Files in Human Readable Format"></p><p><em>以易读格式的长列表列出文件</em></p><pre><code># ls -hs
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/List-File-Sizes-in-Readable-Format.gif" alt="List File Sizes in Long List Format"></p><p><em>以易读格式的短列表列出文件</em></p><p><strong>注意</strong>： ‘-h’选项使用1024（计算机中的标准）的幂，文件或文件夹的大小分别以K，M和G作为输出单位。</p><h3 id="_18-既然-h-选项是使用1024的幂作为标准来输出大小-那么ls命令是否还支持其他的幂值呢" tabindex="-1">18. 既然‘-h’选项是使用1024的幂作为标准来输出大小，那么ls命令是否还支持其他的幂值呢？### <a class="header-anchor" href="#_18-既然-h-选项是使用1024的幂作为标准来输出大小-那么ls命令是否还支持其他的幂值呢" aria-label="Permalink to “18. 既然‘-h’选项是使用1024的幂作为标准来输出大小，那么ls命令是否还支持其他的幂值呢？###”">​</a></h3><p>存在一个选项 ‘--si’与选项‘-h’相似，不同之处在于前者以使用1000的幂，后者使用1024的幂。</p><pre><code># ls --si
</code></pre><p>所以&#39;--si&#39;也可以与‘-l’选项一起使用来按照1000的幂来输出文件夹的大小，并且以长列表格式显示。</p><pre><code># ls --si -l
</code></pre><p>（LCTT 译注：此处原文参数有误，附图也不对，因此删除之）</p><h3 id="_19-假如要你使用逗号-作为分隔符来打印一个目录中的内容-可以吗-对于长列表形式也可行吗" tabindex="-1">19. 假如要你使用逗号‘,’作为分隔符来打印一个目录中的内容，可以吗？ 对于长列表形式也可行吗？### <a class="header-anchor" href="#_19-假如要你使用逗号-作为分隔符来打印一个目录中的内容-可以吗-对于长列表形式也可行吗" aria-label="Permalink to “19. 假如要你使用逗号‘,’作为分隔符来打印一个目录中的内容，可以吗？ 对于长列表形式也可行吗？###”">​</a></h3><p>当然！linux的ls命令当与其选项‘-m’一起使用时可以在打印目录内容时以逗号‘,’分割。由于逗号分割的内容是水平填充的，ls命令不能在垂直列出内容时使用逗号来分割内容。</p><pre><code># ls -m
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Print-Contents-of-Directory-by-Comma.gif" alt="Print Contents of Directory by Comma"></p><p><em>以逗号分隔显示内容</em></p><p>当使用长列表格式时，‘-m’选项就没有什么效果了。</p><pre><code># ls -ml
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Listing-Content-Horizentally.gif" alt="Listing Content Horizontally"></p><p><em>长列表不能使用逗号分隔列表</em></p><h3 id="_20-有办法将目录的内容逆序打印出来吗" tabindex="-1">20. 有办法将目录的内容逆序打印出来吗？### <a class="header-anchor" href="#_20-有办法将目录的内容逆序打印出来吗" aria-label="Permalink to “20. 有办法将目录的内容逆序打印出来吗？###”">​</a></h3><p>可以！上面的情形可以轻松地通过&#39;-r&#39;选项搞定，该选项将输出顺序倒置。这个选项也可以与‘-l’选项一起使用。</p><pre><code># ls -r
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/List-Content-in-Reverse-Order.gif" alt="List Content in Reverse Order"></p><p><em>逆序列出</em></p><pre><code># ls -rl
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Long-List-Content-in-Reverse-Order.gif" alt="Long List Content in Reverse Order"></p><p><em>逆序长列表</em></p><h3 id="_21-如果你被分配一个任务-来递归地打印各个子目录-你会如何应付-注意-只针对子目录而不是文件哦。" tabindex="-1">21. 如果你被分配一个任务，来递归地打印各个子目录，你会如何应付？注意，只针对子目录而不是文件哦。### <a class="header-anchor" href="#_21-如果你被分配一个任务-来递归地打印各个子目录-你会如何应付-注意-只针对子目录而不是文件哦。" aria-label="Permalink to “21. 如果你被分配一个任务，来递归地打印各个子目录，你会如何应付？注意，只针对子目录而不是文件哦。###”">​</a></h3><p>小意思！使用“-R”选项就可以轻轻松松拿下，它也可以更进一步地与其他选项如‘-l’和‘-m’选项等组合使用。</p><pre><code># ls -R
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Print-Sub-Directories-in-Recursively.gif" alt="Print Sub Directories in Recursively"></p><p><em>递归列出子目录</em></p><h3 id="_22-如何按照文件大小对其进行排序" tabindex="-1">22. 如何按照文件大小对其进行排序？### <a class="header-anchor" href="#_22-如何按照文件大小对其进行排序" aria-label="Permalink to “22. 如何按照文件大小对其进行排序？###”">​</a></h3><p>linux命令行选项&#39;-S&#39;赋予了ls命令这个超能力。按照文件大小从大到小的顺序排序：</p><pre><code># ls -S
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Sort-Files-in-Linux.gif" alt="Sort Files with ls Command"><em>按文件大小排序</em></p><p>按照文件大小从小到大的顺序排序。</p><pre><code># ls -Sr
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Sort-Files-in-Descending-Order.gif" alt="Sort Files in Descending Order"></p><p><em>从小到大的排序</em></p><h3 id="_23-按照一行一个文件列出目录中的内容-并且不带额外信息的方式" tabindex="-1">23. 按照一行一个文件列出目录中的内容，并且不带额外信息的方式 <a class="header-anchor" href="#_23-按照一行一个文件列出目录中的内容-并且不带额外信息的方式" aria-label="Permalink to “23. 按照一行一个文件列出目录中的内容，并且不带额外信息的方式”">​</a></h3><p>选项‘-1’在此可以解决这个问题，使用‘-1’选项来使用ls命令可以将目录中的内容按照一行一个文件并且不带额外信息的方式进行输出。</p><pre><code># ls -1
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/List-Files-Without-Information.gif" alt="List Files Without Information"></p><p><em>不带其他信息，一行一个列出文件</em></p><h3 id="_24-现在委派给你一个任务-你必须将目录中的内容输出到终端而且需要使用双引号引起来-你会如何做" tabindex="-1">24. 现在委派给你一个任务，你必须将目录中的内容输出到终端而且需要使用双引号引起来，你会如何做？### <a class="header-anchor" href="#_24-现在委派给你一个任务-你必须将目录中的内容输出到终端而且需要使用双引号引起来-你会如何做" aria-label="Permalink to “24. 现在委派给你一个任务，你必须将目录中的内容输出到终端而且需要使用双引号引起来，你会如何做？###”">​</a></h3><p>有一个选项‘-Q’会将ls命令的输出内容用双引号引起来。</p><pre><code># ls -Q
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Print-Files-with-Double-Quotes.gif" alt="Print Files with Double Quotes"></p><p><em>输出的文件名用引号引起来</em></p><h3 id="_25-想象一下你正在与一个包含有很多文件和文件夹的目录打交道-你需要使目录名显示在文件名之前-你如何做" tabindex="-1">25. 想象一下你正在与一个包含有很多文件和文件夹的目录打交道，你需要使目录名显示在文件名之前，你如何做？### <a class="header-anchor" href="#_25-想象一下你正在与一个包含有很多文件和文件夹的目录打交道-你需要使目录名显示在文件名之前-你如何做" aria-label="Permalink to “25. 想象一下你正在与一个包含有很多文件和文件夹的目录打交道，你需要使目录名显示在文件名之前，你如何做？###”">​</a></h3><pre><code># ls --group-directories-first
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Print-Directories-First.gif" alt="Print Directories First"></p><p><em>目录优先显示</em></p><p>先点到为止，我们会马上提供该系列文章的下一部分。别换频道，关注我们。 另外别忘了在下面的评论中提出你们宝贵的反馈信息，喜欢就分享，帮助我们得到更好的传播吧!</p><hr>`,81)),i("p",null,[e[2]||(e[2]=t("via: ",-1)),s(n,{href:"http://www.tecmint.com/ls-interview-questions/"},{default:r(()=>[...e[1]||(e[1]=[t("http://www.tecmint.com/ls-interview-questions/",-1)])]),_:1})]),i("p",null,[e[6]||(e[6]=t("作者：",-1)),s(n,{href:"http://www.tecmint.com/author/admin/"},{default:r(()=>[...e[3]||(e[3]=[t("Ravi Saive",-1)])]),_:1}),e[7]||(e[7]=t(" 译者：",-1)),s(n,{href:"https://github.com/theo-l"},{default:r(()=>[...e[4]||(e[4]=[t("theo-l",-1)])]),_:1}),e[8]||(e[8]=t(" 校对：",-1)),s(n,{href:"https://github.com/wxy"},{default:r(()=>[...e[5]||(e[5]=[t("wxy",-1)])]),_:1})]),i("p",null,[e[11]||(e[11]=t("本文由 ",-1)),s(n,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[9]||(e[9]=[t("LCTT",-1)])]),_:1}),e[12]||(e[12]=t(" 原创翻译，",-1)),s(n,{href:"http://linux.cn/"},{default:r(()=>[...e[10]||(e[10]=[t("Linux中国",-1)])]),_:1}),e[13]||(e[13]=t(" 荣誉推出",-1))])])}const P=o(d,[["render",c]]);export{C as __pageData,P as default};
